-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10615, 39, 'Grunderwerbsteuer-Freibetrag oder -Befreiung für (erst)selbstgenutztes Wohneigentum (Land)', 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'gemischt', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'land', null, true, 'blind', null),
  (10616, 39, 'Grunderwerbsteuersatz allgemein senken (Land)', 'Senkt die Nebenkosten für alle Käufer, Land ist zuständig; dagegen sprechen hohe Einnahmeausfälle und dass Preise teils mitsteigen (Studien zu Satzänderungen).', 'gemischt', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'land', null, true, 'blind', null),
  (10617, 39, 'Grunderwerbsteuersatz anheben (Land)', 'Erhöht die Erwerbsnebenkosten statt sie zu senken; Studien zeigen zwar teilweise sinkende Preise, für Käufer bleibt aber keine Entlastung beim Eigenkapital für Nebenkosten.', 'gemischt', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'land', null, true, 'blind', null),
  (10618, 39, 'Grunderwerbsteuer-Freibetrag oder -Befreiung für selbstgenutztes Wohneigentum (Bund)', 'Senkt die Nebenkosten beim Kauf deutlich; Teil der Entlastung kann in Preise übergehen. Bund kann das Grunderwerbsteuergesetz ändern, braucht aber den Bundesrat, da das Aufkommen den Ländern zusteht.', 'gemischt', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'bund', null, true, 'blind', null),
  (10619, 39, 'Erbschaftsteuer senken, abschaffen oder Freibeträge erhöhen (Bund)', 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'gemischt', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'bund', null, true, 'blind', null),
  (10620, 39, 'Wohnungsbau- bzw. Sparprämie erhöhen und dynamisieren (Bund)', 'Evaluation zeigt: Geförderte sparen mehr und erwerben früher Eigentum; die Beträge sind aber klein und erreichen Geringverdiener bisher kaum. Bund betreibt die Förderung bereits.', 'belegt', 'https://www.diw.de/de/diw_01.c.822044.de/s_12953.html', 'bund', null, true, 'blind', null),
  (10621, 39, 'Mehr Bauland ausweisen und Ausweisung vereinfachen (Bund)', 'Restriktive Flächenregeln gehen laut OECD mit geringerem Angebot und höheren Preisen einher; die Ausweisung liegt aber bei den Kommunen, der Bund kann nur Rahmen und eigene Flächen beitragen.', 'belegt', 'https://oecdecoscope.blog/2021/07/02/a-recipe-for-lower-house-prices/', 'bund', null, true, 'blind', null),
  (10622, 39, 'Planungs- und Genehmigungsverfahren beschleunigen und digitalisieren (Bund)', 'Kürzere Verfahren können Flächen schneller nutzbar machen, schaffen aber kein zusätzliches Bauland; Baugenehmigungen regeln die Länder, Umweltprüfungen teils EU-Recht.', 'gemischt', null, 'bund', null, true, 'blind', null),
  (10623, 39, 'Aktive kommunale Bodenpolitik: Bodenfonds und Vorkaufsrechte stärken (Bund)', 'Kommunaler Flächenerwerb kann Bauland mobilisieren und günstiger vergeben; Wirkung auf Eigentumserwerb kaum untersucht, Ankauf auf teuren Märkten schwierig.', 'offen', null, 'bund', null, true, 'blind', null),
  (10624, 39, 'Planungsbedingte Bodenwertsteigerungen abschöpfen (Bund)', 'Kann Spekulation und Horten von Bauland weniger lohnend machen; ob dadurch mehr Flächen bebaut werden oder Kosten an Käufer weitergegeben werden, ist kaum untersucht.', 'offen', null, 'bund', null, true, 'blind', null),
  (10625, 39, 'Bauvorschriften und Baustandards abbauen und vereinfachen (Bund)', 'Studien sehen Vorgaben als großen Kostentreiber im Neubau, die Größenordnung ist umstritten; Bauordnungen sind Landesrecht, der Bund kann nur Teile regeln.', 'gemischt', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'bund', null, true, 'blind', null),
  (10626, 39, 'Serielles und modulares Bauen fördern und Genehmigungen vereinheitlichen (Bund)', 'Vorfertigung verkürzt Bauzeiten und senkt Kostenrisiken; belastbare Kostensenkungen sind bislang nicht unabhängig belegt und betreffen eher Mehrfamilienhäuser.', 'gemischt', null, 'bund', null, true, 'blind', null),
  (10627, 39, 'Heizungsvorgaben des Gebäudeenergiegesetzes abschaffen (Bund)', 'Im Neubau sind Wärmepumpen ohnehin verbreitet, die Kostenersparnis ist gering; ein ersatzloses Auslaufen kollidiert mit der Umsetzung der EU-Gebäuderichtlinie.', 'offen', null, 'bund', null, true, 'blind', null),
  (10628, 39, 'Zinsverbilligte Förderkredite für selbstgenutztes Wohneigentum ausbauen (Bund)', 'Senkt die laufende Rate direkt, Bund finanziert die Programme bereits; bisher geringe Nachfrage wegen enger Grenzen und Auflagen, und Subventionen können in Preise übergehen.', 'gemischt', null, 'bund', null, true, 'blind', null)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
