insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft, nebenwirkungen) values
  (10629, 39, 11, null, 'Mehr Bauland für den Neubau ausweisen, auch durch Nutzung von Brach- und Konversionsflächen und Bundesgrundstücken.', '{3901}', 10621, 2, 2, null, 'Restriktive Flächenregeln gehen laut OECD mit geringerem Angebot und höheren Preisen einher; die Ausweisung liegt aber bei den Kommunen, der Bund kann nur Rahmen und eigene Flächen beitragen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', 'https://oecdecoscope.blog/2021/07/02/a-recipe-for-lower-house-prices/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10630, 39, 11, null, 'Planungs- und Genehmigungsverfahren für Bauleitplanung und Baugenehmigung digitalisieren und beschleunigen.', '{3901}', 10622, 1, 2, null, 'Kürzere Verfahren können Flächen schneller nutzbar machen, schaffen aber kein zusätzliches Bauland; Baugenehmigungen regeln die Länder, Umweltprüfungen teils EU-Recht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10631, 39, 11, null, 'Befristete Ausnahmen vom Planungsrecht für Wohnungsbauvorhaben in angespannten Märkten.', '{3901}', null, 2, 3, null, 'Erlaubt Wohnungsbau ohne neuen Bebauungsplan und kann Flächen schnell nutzbar machen; seit 2025 in Kraft, Wirkung noch kaum untersucht und abhängig von der Zustimmung der Gemeinden.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10632, 39, 11, null, 'Bauordnungs- und Raumordnungsrecht entschlacken und Vorschriften spürbar reduzieren.', '{3902}', 10625, 2, 2, null, 'Studien sehen Vorgaben als großen Kostentreiber im Neubau, die Größenordnung ist umstritten; Bauordnungen sind Landesrecht, der Bund kann nur Teile regeln.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10633, 39, 11, null, 'Keine neuen Standards, die Baukosten ohne nennenswerten Mehrwert erhöhen.', '{3902}', null, 1, 3, null, 'Verhindert nur weitere Kostensteigerungen durch neue Standards, senkt bestehende Baukosten nicht; leicht umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10634, 39, 11, null, 'Vermögensbildungsprämie einführen, die Arbeitnehmersparzulage und Wohnungsbauprämie zusammenführt und den Förderbetrag erhöht.', '{3903}', 10620, 2, 3, null, 'Evaluation zeigt: Geförderte sparen mehr und erwerben früher Eigentum; die Beträge sind aber klein und erreichen Geringverdiener bisher kaum. Bund betreibt die Förderung bereits.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', 'https://www.diw.de/de/diw_01.c.822044.de/s_12953.html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10635, 39, 11, null, 'Freibeträge bei der Erbschaftsteuer erhöhen, damit das Eigenheim in höherem Maße steuerfrei vererbt werden kann.', '{3903}', 10619, 1, 2, null, 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10636, 39, 11, null, 'Länder sollen einen Freibetrag bei der Grunderwerbsteuer für den ersten Erwerb selbstgenutzten Wohneigentums gewähren können.', '{3904}', 10618, 2, 2, null, 'Senkt die Nebenkosten beim Kauf deutlich; Teil der Entlastung kann in Preise übergehen. Bund kann das Grunderwerbsteuergesetz ändern, braucht aber den Bundesrat, da das Aufkommen den Ländern zusteht.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=34', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10637, 39, 11, null, 'Bestehende Förderprogramme der Zinsverbilligung neu ausrichten: Einkommensgrenzen anheben, Kauf von Bestandsimmobilien einbeziehen.', '{3905}', 10628, 2, 3, null, 'Senkt die laufende Rate direkt, Bund finanziert die Programme bereits; bisher geringe Nachfrage wegen enger Grenzen und Auflagen, und Subventionen können in Preise übergehen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=73', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10638, 39, 11, 'BE', 'Grunderwerbsteuer beim ersten selbstgenutzten Wohneigentum deutlich senken, Teilerlass bis zu einem Kaufpreisanteil', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=33', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10639, 39, 11, 'MV', 'Senkung der Grunderwerbsteuer als weitere Zielstellung neben dem Baukindergeld', '{3904}', 10616, 2, 2, null, 'Senkt die Nebenkosten für alle Käufer, Land ist zuständig; dagegen sprechen hohe Einnahmeausfälle und dass Preise teils mitsteigen (Studien zu Satzänderungen).', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=6', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10640, 39, 11, 'ST', 'Grunderwerbsteuer beim ersten selbstgenutzten Eigenheim im ländlichen Raum entfallen lassen', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=31', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10641, 39, 12, null, 'Genehmigungsfiktion: Anträge gelten nach Fristablauf als genehmigt, auch für Bau- und Investitionsprojekte', '{3901}', 10622, 1, 2, null, 'Kürzere Verfahren können Flächen schneller nutzbar machen, schaffen aber kein zusätzliches Bauland; Baugenehmigungen regeln die Länder, Umweltprüfungen teils EU-Recht.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=38', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10642, 39, 12, null, 'Kommunen beim Aufbau von Bodenfonds unterstützen', '{3901}', 10623, 1, 2, null, 'Kommunaler Flächenerwerb kann Bauland mobilisieren und günstiger vergeben; Wirkung auf Eigentumserwerb kaum untersucht, Ankauf auf teuren Märkten schwierig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10643, 39, 12, null, 'Vorkaufsrecht für Kommunen stärken', '{3901}', 10623, 1, 2, null, 'Kommunaler Flächenerwerb kann Bauland mobilisieren und günstiger vergeben; Wirkung auf Eigentumserwerb kaum untersucht, Ankauf auf teuren Märkten schwierig.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10644, 39, 12, null, 'Vereinfachte Baustandards wie den Gebäudetyp E weiterentwickeln', '{3902}', null, 2, 3, null, 'Pilotprojekte melden rund 15 % geringere Bauwerkskosten durch Verzicht auf nicht nötige Standards; eine unabhängige Gesamtauswertung steht noch aus.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', 'https://stmb.bayern.de/med/pressemitteilungen/pressearchiv/2025/112/index.php', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10645, 39, 12, null, 'Serielles und modulares Bauen fördern', '{3902}', 10626, 1, 2, null, 'Vorfertigung verkürzt Bauzeiten und senkt Kostenrisiken; belastbare Kostensenkungen sind bislang nicht unabhängig belegt und betreffen eher Mehrfamilienhäuser.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10646, 39, 12, null, 'Freibeträge bei Erbschaft und Schenkung erhöhen', '{3903}', 10619, 1, 2, null, 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=19', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10647, 39, 12, null, 'Förderprogramm Jung kauft Alt verstetigen und ausbauen, mit zinsgünstigen Krediten für junge Familien', '{3905}', 10628, 2, 3, null, 'Senkt die laufende Rate direkt, Bund finanziert die Programme bereits; bisher geringe Nachfrage wegen enger Grenzen und Auflagen, und Subventionen können in Preise übergehen.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=22', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10648, 39, 12, 'BE', 'Grunderwerbsteuer um 0,5 Prozentpunkte anheben; große Unternehmen sollen mehr zahlen, Selbstnutzer sollen ausgenommen werden', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=63', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10649, 39, 12, 'BE', 'Grunderwerbsteuer für selbstgenutztes Eigentum absenken, sobald Share Deals auf Bundesebene unterbunden sind (bedingte Zusage)', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=63', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10650, 39, 12, 'ST', 'Ersterwerb von Immobilien für natürliche Personen von der Grunderwerbsteuer befreien (Forderung an den Bund)', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=54', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10651, 39, 13, null, 'Förderung von Kauf und Neubau selbst genutzten Wohneigentums über zinsgünstige staatliche Kredite, vor allem für junge Familien', '{3905}', 10628, 2, 3, null, 'Senkt die laufende Rate direkt, Bund finanziert die Programme bereits; bisher geringe Nachfrage wegen enger Grenzen und Auflagen, und Subventionen können in Preise übergehen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=70', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10652, 39, 13, null, 'Wohnungsbauprämie, deren Höhe mit der Inflation steigt, für den Zugang zu Wohneigentum', '{3903}', 10620, 2, 3, null, 'Evaluation zeigt: Geförderte sparen mehr und erwerben früher Eigentum; die Beträge sind aber klein und erreichen Geringverdiener bisher kaum. Bund betreibt die Förderung bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=70', 'https://www.diw.de/de/diw_01.c.822044.de/s_12953.html', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10653, 39, 13, null, 'Entlastung bei den Nebenkosten des Kaufs wie Makler- und Notargebühren', '{3904}', null, 1, 2, null, 'Bund regelt Notargebühren und Maklerrecht, die Maklerkosten wurden 2020 schon geteilt; ohne konkrete Höhe bleibt die Entlastung unbestimmt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=70', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10654, 39, 13, null, 'Flächenzertifikatehandel zur Begrenzung des Flächenverbrauchs, Ziel 30 Hektar pro Tag bis 2030', '{3901}', null, 0, 1, null, 'Begrenzt neue Bauflächen und kann Innenentwicklung anreizen; für Eigentumserwerb ist eher ein knapperes Flächenangebot zu erwarten. Bundesweiter Handel braucht Länder und Kommunen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10655, 39, 13, null, 'Bodenpolitik am Gemeinwohl ausrichten, Bundesbodenfonds einrichten, kommunale Bodenfonds unterstützen', '{3901}', 10623, 1, 2, null, 'Kommunaler Flächenerwerb kann Bauland mobilisieren und günstiger vergeben; Wirkung auf Eigentumserwerb kaum untersucht, Ankauf auf teuren Märkten schwierig.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10656, 39, 13, null, 'Städtebauförderung aufstocken und Innenentwicklung vereinfachen', '{3901}', null, 1, 3, null, 'Erleichterte Innenentwicklung kann Baulücken und Brachen nutzbar machen; Städtebauförderung zielt aber vor allem auf Quartiersaufwertung. Bund finanziert sie bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=73', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10657, 39, 13, null, 'Baurecht vereinfachen und Verfahren bundesweit angleichen, auch zur Digitalisierung', '{3902}', 10625, 2, 2, null, 'Studien sehen Vorgaben als großen Kostentreiber im Neubau, die Größenordnung ist umstritten; Bauordnungen sind Landesrecht, der Bund kann nur Teile regeln.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10658, 39, 13, null, 'Serielles Bauen von Wohngebäuden stärken', '{3902}', 10626, 1, 2, null, 'Vorfertigung verkürzt Bauzeiten und senkt Kostenrisiken; belastbare Kostensenkungen sind bislang nicht unabhängig belegt und betreffen eher Mehrfamilienhäuser.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=71', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10659, 39, 13, 'BE', 'Grunderwerbsteuer für Menschen, die selbst im Eigenheim wohnen wollen, sozial staffeln und senken.', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=52', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10660, 39, 13, 'BE', 'Grunderwerbsteuer an den Steuersatz von Brandenburg anpassen.', '{3904}', null, 0, 3, null, 'Angleichung an den Satz eines anderen Landes; eine Entlastung bei den Nebenkosten ist nicht erkennbar, die Richtung bleibt offen.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=124', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10661, 39, 14, null, 'Genehmigungsverfahren beschleunigen, überflüssige Umweltgutachten abschaffen, Vorrang für Wohnungsbau.', '{3901}', 10622, 1, 2, null, 'Kürzere Verfahren können Flächen schneller nutzbar machen, schaffen aber kein zusätzliches Bauland; Baugenehmigungen regeln die Länder, Umweltprüfungen teils EU-Recht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10662, 39, 14, null, 'Ausweisung neuer Bauflächen vereinfachen, auch durch Nachverdichtung und Aufstockung.', '{3901}', 10621, 2, 2, null, 'Restriktive Flächenregeln gehen laut OECD mit geringerem Angebot und höheren Preisen einher; die Ausweisung liegt aber bei den Kommunen, der Bund kann nur Rahmen und eigene Flächen beitragen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', 'https://oecdecoscope.blog/2021/07/02/a-recipe-for-lower-house-prices/', 'belegt', '2026-10-21', false, true, 'blind', null),
  (10663, 39, 14, null, 'Serielles Bauen durch einheitliche Anforderungen und bundesweite Genehmigungsstandards voranbringen.', '{3902}', 10626, 1, 2, null, 'Vorfertigung verkürzt Bauzeiten und senkt Kostenrisiken; belastbare Kostensenkungen sind bislang nicht unabhängig belegt und betreffen eher Mehrfamilienhäuser.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10664, 39, 14, null, 'Überzogene Bau-Auflagen abbauen und auf Mindeststandards reduzieren.', '{3902}', 10625, 2, 2, null, 'Studien sehen Vorgaben als großen Kostentreiber im Neubau, die Größenordnung ist umstritten; Bauordnungen sind Landesrecht, der Bund kann nur Teile regeln.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=44', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10665, 39, 14, null, 'Heizungsgesetz mit seinen Vorgaben vollständig auslaufen lassen.', '{3902}', 10627, 1, 2, null, 'Im Neubau sind Wärmepumpen ohnehin verbreitet, die Kostenersparnis ist gering; ein ersatzloses Auslaufen kollidiert mit der Umsetzung der EU-Gebäuderichtlinie.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10666, 39, 14, null, 'Grunderwerbsteuerfreibetrag von 500.000 Euro für die erste selbst genutzte Immobilie, plus 100.000 Euro je Kind.', '{3904}', 10618, 2, 2, null, 'Senkt die Nebenkosten beim Kauf deutlich; Teil der Entlastung kann in Preise übergehen. Bund kann das Grunderwerbsteuergesetz ändern, braucht aber den Bundesrat, da das Aufkommen den Ländern zusteht.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10667, 39, 14, null, 'Freibeträge der Erbschaft- und Schenkungsteuer automatisch an die Inflation anpassen.', '{3903}', 10619, 1, 2, null, 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=15', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10668, 39, 14, null, 'Mittel aus der betrieblichen Altersvorsorge für den Eigentumserwerb nutzbar machen.', '{3903}', null, 2, 2, null, 'Schafft eine zusätzliche Eigenkapitalquelle, in der Schweiz verbreitet genutzt; dagegen sprechen geschwächte Altersvorsorge und dass nur Beschäftigte mit Betriebsrente profitieren.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=45', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10669, 39, 14, 'BE', 'Grunderwerbsteuer beim Kauf selbst genutzter Immobilien senken: die ersten 750.000 Euro steuerfrei, gegenfinanziert durch Verkauf landeseigener Grundstücke', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=47', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10670, 39, 14, 'MV', 'Grunderwerbsteuersatz wieder auf 3,5 Prozent absenken', '{3904}', 10616, 2, 2, null, 'Senkt die Nebenkosten für alle Käufer, Land ist zuständig; dagegen sprechen hohe Einnahmeausfälle und dass Preise teils mitsteigen (Studien zu Satzänderungen).', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=71', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10671, 39, 14, 'ST', 'Grunderwerbsteuer-Freibetrag für den ersten Erwerb selbstgenutzten Wohneigentums, zusammen mit einem Landesförderprogramm; Einsatz dafür auf Bundesebene.', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=11', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10672, 39, 15, null, 'Genehmigungsrecht für Ersatzbauten von Wohngebäuden im Außenbereich ermöglichen', '{3901}', null, 1, 3, null, 'Erleichtert Ersatzneubau auf bereits bebauten Außenbereichsflächen; betrifft nur wenige Fälle und schafft kaum neues Bauland. Bund ist für das Bauplanungsrecht zuständig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=40', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10673, 39, 15, null, 'Gesetzliche Vorgaben zum Bau- und Mietrecht zurückführen, um Wohnungsbau zu erleichtern', '{3902}', 10625, 2, 2, null, 'Studien sehen Vorgaben als großen Kostentreiber im Neubau, die Größenordnung ist umstritten; Bauordnungen sind Landesrecht, der Bund kann nur Teile regeln.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10674, 39, 15, null, 'Gebäudeenergiegesetz abschaffen (zusammen mit EEG-Umlage und CO₂-Steuer)', '{3902}', null, 1, 0, null, 'Energievorgaben tragen zu Baukosten bei, ihr Anteil ist umstritten; das GEG setzt die EU-Gebäuderichtlinie um, eine ersatzlose Abschaffung wäre EU-rechtswidrig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', 'https://www.baulinks.de/webplugin/2015/0702.php4', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10675, 39, 15, null, 'Eigenkapitalersatz für Mieter beim Kauf selbstgenutzten Wohneigentums', '{3903}', null, 2, 2, null, 'Setzt direkt an der Eigenkapitalhürde an; Erfahrungen mit Help to Buy zeigen aber steigende Preise in knappen Märkten. Ausgestaltung und Finanzierung sind offen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=38', 'https://researchonline.lse.ac.uk/id/eprint/120627/', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10676, 39, 15, null, 'Erbschaftsteuer und Vermögensteuer abschaffen', '{3903}', 10619, 1, 2, null, 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10677, 39, 15, null, 'Grunderwerbsteuer für selbstnutzende Käufer abschaffen, dazu Grundsteuer und Rundfunkbeitrag', '{3904}', 10618, 2, 2, null, 'Senkt die Nebenkosten beim Kauf deutlich; Teil der Entlastung kann in Preise übergehen. Bund kann das Grunderwerbsteuergesetz ändern, braucht aber den Bundesrat, da das Aufkommen den Ländern zusteht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=37', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10678, 39, 15, null, 'Sparerpauschbetrag auf 6.672 Euro erhöhen und an die Geringfügigkeitsgrenze koppeln', '{3903}', null, 1, 2, null, 'Höhere steuerfreie Zinserträge erleichtern das Ansparen nur geringfügig und vor allem bei bereits größeren Ersparnissen; Steuerausfälle sind erheblich.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=61', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10679, 39, 15, null, 'Mieter sollen Wohnungen aus öffentlichem Wohnungsbestand zu vergünstigten Bedingungen erwerben können', '{3903}', null, 1, 2, null, 'Vergünstigter Kauf senkt den Eigenkapitalbedarf einzelner Mieter; der öffentliche Bestand ist begrenzt und meist kommunal, preisgünstiger Mietbestand geht verloren.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=38', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10680, 39, 15, 'BE', 'Grunderwerbsteuer für Ersterwerber selbstgenutzten Wohneigentums abschaffen; für außerhalb des EU-Raums ansässige Investoren eine Steuer einführen', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=9', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10681, 39, 15, 'MV', 'Grunderwerbsteuer für die erste selbstgenutzte Immobilie abschaffen', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=55', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10682, 39, 15, 'ST', 'Grunderwerbsteuer von 5 auf 2,5 Prozent absenken.', '{3904}', 10616, 2, 2, null, 'Senkt die Nebenkosten für alle Käufer, Land ist zuständig; dagegen sprechen hohe Einnahmeausfälle und dass Preise teils mitsteigen (Studien zu Satzänderungen).', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=228', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10683, 39, 16, null, 'Selbstgenutztes Wohneigentum bei Erbschaften bis 200 Quadratmeter von der Erbschaftsteuer befreien.', '{3903}', 10619, 1, 2, null, 'Familientransfers erleichtern den Eigentumserwerb, doch die meisten Erbschaften liegen unter den Freibeträgen und große Transfers gehen an bereits Vermögende; Bundesrat muss zustimmen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=11', 'https://www.diw.de/de/diw_01.c.809938.de/erbschaften_machen_vor_allem_vermoegende_noch_reicher.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10684, 39, 16, null, 'Leistungslose Bodenwertzuwächse abschöpfen, um Spekulation mit Bauland zu bremsen.', '{3901}', 10624, 1, 2, null, 'Kann Spekulation und Horten von Bauland weniger lohnend machen; ob dadurch mehr Flächen bebaut werden oder Kosten an Käufer weitergegeben werden, ist kaum untersucht.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=9', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10685, 39, 16, 'BE', 'Grunderwerbsteuer auf mindestens 6,5, möglichst 8,0 Prozent anheben', '{3904}', 10617, 0, 3, null, 'Erhöht die Erwerbsnebenkosten statt sie zu senken; Studien zeigen zwar teilweise sinkende Preise, für Käufer bleibt aber keine Entlastung beim Eigenkapital für Nebenkosten.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=79', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10686, 39, 16, 'BE', 'Länder sollen Steuersatz differenzieren, damit selbst genutztes Wohneigentum und sozialer Wohnungsbau ausgenommen werden können', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=79', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10687, 39, 17, null, 'Familien beim Erwerb des ersten selbstgenutzten Eigenheims von der Grunderwerbsteuer befreien', '{3904}', 10618, 2, 2, null, 'Senkt die Nebenkosten beim Kauf deutlich; Teil der Entlastung kann in Preise übergehen. Bund kann das Grunderwerbsteuergesetz ändern, braucht aber den Bundesrat, da das Aufkommen den Ländern zusteht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=17', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10688, 39, 17, null, 'Spekulation mit Bauland eindämmen und aktive Bodenpolitik betreiben', '{3901}', 10623, 1, 2, null, 'Kommunaler Flächenerwerb kann Bauland mobilisieren und günstiger vergeben; Wirkung auf Eigentumserwerb kaum untersucht, Ankauf auf teuren Märkten schwierig.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10689, 39, 17, null, 'Planungsbedingte Wertsteigerungen von Grundstücken abschöpfen', '{3901}', 10624, 1, 2, null, 'Kann Spekulation und Horten von Bauland weniger lohnend machen; ob dadurch mehr Flächen bebaut werden oder Kosten an Käufer weitergegeben werden, ist kaum untersucht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10690, 39, 17, null, 'Beschleunigung von Bauvorhaben, Vereinfachung seriellen Bauens und vereinfachte Genehmigung', '{3901}', 10622, 1, 2, null, 'Kürzere Verfahren können Flächen schneller nutzbar machen, schaffen aber kein zusätzliches Bauland; Baugenehmigungen regeln die Länder, Umweltprüfungen teils EU-Recht.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=28', null, 'gemischt', '2026-10-21', false, true, 'blind', null),
  (10691, 39, 17, null, 'Heizungsgesetz abschaffen und durch andere Regelungen ersetzen', '{3902}', 10627, 1, 2, null, 'Im Neubau sind Wärmepumpen ohnehin verbreitet, die Kostenersparnis ist gering; ein ersatzloses Auslaufen kollidiert mit der Umsetzung der EU-Gebäuderichtlinie.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=10', null, 'offen', '2026-10-21', false, true, 'blind', null),
  (10692, 39, 17, 'ST', 'Freibeträge bei der Grunderwerbsteuer als Teil eines Bau-Beschleunigungspakets unterstützen', '{3904}', 10615, 2, 1, null, 'Senkt die Erwerbsnebenkosten direkt; Studien zeigen aber, dass Preise stark auf die Steuer reagieren, ein Teil der Entlastung kann in Kaufpreise fließen. Länder dürfen nur den Satz festlegen, Freibeträge brauchen ein Bundesgesetz.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=31', 'https://ideas.repec.org/p/ces/ceswps/_8839.html', 'gemischt', '2026-10-21', false, true, 'blind', null);

